            await page.click('[data-tile-select="0"]').catch(() => {});
            TILE_SAVED.savedAfter = await page.$eval("[data-tile-saved-where]", (e) => (e.textContent ?? "").trim()).catch(() => null);
            await page.keyboard.press("Escape").catch(() => {});
